const warned = new Set<string>();

/**
 * DEV 期一次性告警。同一 `key` 全程只警一次。这些告警都在 render 或每渲染的 effect 里调用，
 * 不去重会刷屏。`key` 只用于去重、不出现在输出里；`message` 自带来源前缀。
 *
 * 生产构建下 `import.meta.env.DEV` 是字面 `false`，整个函数体被 DCE 掉。该守卫依赖 Vite 的
 * `import.meta.env`（TanStack Start 即 Vite）；非 Vite 构建下需自行替换成等价的环境判断。
 */
export function devWarn(key: string, message: string): void {
  if (!import.meta.env.DEV) return;
  if (warned.has(key)) return;
  warned.add(key);
  console.warn(message);
}

import {
  type ColumnDef,
  columnVisibilityFeature,
  createColumnHelper,
  type ReactTable,
  type RowData,
  rowPaginationFeature,
  rowSelectionFeature,
  rowSortingFeature,
  type Table,
  tableFeatures,
} from "@tanstack/react-table";
import type { ReactNode } from "react";

/** 基础特性映射；供 DataTable 与调用方追加特性时做加法合并。 */
export const baseFeatureMap = {
  rowSortingFeature,
  rowPaginationFeature,
  columnVisibilityFeature,
  rowSelectionFeature,
};

/** 全表共用的 v9 特性集；少注册一个对应方法即编译期消失。 */
export const features = tableFeatures(baseFeatureMap);

export type TableFeatures = typeof features;

/** DataTable 内部构造的表实例类型（按基础特性定型）。`useDataTable()` 的调用方在自己的组件
 * 作用域里直接拿到它（`dt.table`）；`DataTable` 的 `footer` 回调另外单独给一份。 */
export type TableInstance<TData extends RowData> = ReactTable<TableFeatures, TData>;

/** 列 `cell` 上下文给出的表对象类型，比 `TableInstance` 窄。`ReactTable` 是
 * `Omit<Table, "store"> & { store, state, Subscribe, FlexRender }`，而 `state`/`Subscribe`/
 * `FlexRender` 只挂在 `useTable()` 另行 memo 出的返回对象上，cell 上下文永远拿不到。故行内插槽
 * （`AbpTableRowConfig` 的 `actions`/`menu`，喂给 `RowActionsMenu` 的 `rowActions`/`items` 属性）
 * 一律用这个类型，宁可少承诺也不给说谎的类型；要读当前状态走 `table.store`（本类型含），要完整
 * 实例走调用方自己持有的 `dt.table` 或 `DataTable` 的 `footer` 回调。 */
export type CellTableInstance<TData extends RowData> = Table<TableFeatures, TData>;

/** 绑定好 TFeatures 的列定义别名，消费方只写这个，不感知泛型。 */
export type TableColumnDef<TData extends RowData> = ColumnDef<TableFeatures, TData, unknown>;

export const createTableColumnHelper = <TData extends RowData>() =>
  createColumnHelper<TableFeatures, TData>();

declare module "@tanstack/react-table" {
  interface ColumnMeta<TFeatures, TData, TValue> {
    align?: "left" | "right" | "center";
    className?: string;
    label?: ReactNode;
  }
}

import type {
  OnChangeFn,
  PaginationState,
  RowSelectionState,
  SortingState,
  Updater,
} from "@tanstack/react-table";
import { useCallback, useEffect, useRef, useState } from "react";

const SEARCH_DEBOUNCE_MS = 400;

export type TableDensity = "comfortable" | "compact";

/**
 * 服务端分页表格的状态机：分页/排序/防抖搜索/页内行选择；filter 为已提交的搜索值，
 * searchInput 为输入框即时值。rowSelection 页内作用域，翻页/排序/提交搜索均清空。
 * 结构化查询参数不归这里管，那是 useAbpTable 的表单实例自己持有的东西。
 */
export function useDataTableState(opts: { defaultPageSize?: number } = {}) {
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize: opts.defaultPageSize ?? 10,
  });
  const [sorting, setSorting] = useState<SortingState>([]);
  const [searchInput, setSearchInput] = useState("");
  const [filter, setFilter] = useState("");
  const [rowSelection, setRowSelection] = useState<RowSelectionState>({});
  const [density, setDensity] = useState<TableDensity>("comfortable");
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);

  const clearSelection = useCallback(() => setRowSelection({}), []);

  const resetPaging = useCallback(() => {
    // 新查询从第一页开始，否则会停留在越界页；页内选择同时作废
    setPagination((p) => ({ ...p, pageIndex: 0 }));
    setRowSelection({});
  }, []);

  const commit = useCallback(
    (value: string) => {
      setFilter(value);
      resetPaging();
    },
    [resetPaging],
  );

  const setSearch = useCallback(
    (value: string) => {
      setSearchInput(value);
      clearTimeout(timer.current);
      timer.current = setTimeout(() => commit(value), SEARCH_DEBOUNCE_MS);
    },
    [commit],
  );

  const flushSearch = useCallback(() => {
    clearTimeout(timer.current);
    commit(searchInput);
  }, [commit, searchInput]);

  useEffect(() => () => clearTimeout(timer.current), []);

  const onPaginationChange = useCallback((updater: Updater<PaginationState>) => {
    setPagination(updater);
    setRowSelection({});
  }, []);
  const onSortingChange = useCallback((updater: Updater<SortingState>) => {
    setSorting(updater);
    setRowSelection({});
  }, []);
  const onRowSelectionChange = useCallback<OnChangeFn<RowSelectionState>>((updater) => {
    setRowSelection(updater);
  }, []);

  /** 只保留指定行选中；批量操作部分失败回填用。ids 为 getRowId 产出的行 ID。 */
  const keepSelected = useCallback((ids: string[]) => {
    setRowSelection(Object.fromEntries(ids.map((id) => [id, true])));
  }, []);

  return {
    params: { pageIndex: pagination.pageIndex, pageSize: pagination.pageSize, sorting, filter },
    pagination,
    sorting,
    searchInput,
    setSearch,
    flushSearch,
    resetPaging,
    onPaginationChange,
    onSortingChange,
    rowSelection,
    onRowSelectionChange,
    selectedCount: Object.keys(rowSelection).length,
    clearSelection,
    keepSelected,
    density,
    setDensity,
  };
}

export type DataTableState = ReturnType<typeof useDataTableState>;

import { type Localize, useLocalization } from "@jcoder-stack/abp-react/react";
import {
  type RowData,
  type RowSelectionState,
  type TableOptions,
  tableFeatures,
  useTable,
} from "@tanstack/react-table";
import { createElement, type MouseEvent, useEffect, useMemo, useRef } from "react";
import { devWarn } from "@/components/data-table/dev-warn";
import {
  baseFeatureMap,
  features,
  type TableColumnDef,
  type TableFeatures,
  type TableInstance,
} from "@/components/data-table/table-core";
import {
  type DataTableState,
  useDataTableState,
} from "@/components/data-table/use-data-table-state";
import { Checkbox } from "@/components/ui/checkbox";

/** 共享的空选择态。写成 `?? {}` 每渲染都新建对象，TanStack 按身份比对会当成受控 state 变了，
 *  在「未受控 rowSelection + 其它受控 prop 变化」的组合下自持重渲染。 */
const EMPTY_ROW_SELECTION: RowSelectionState = {};

/** 页内选择列：表头全选（含 indeterminate），行内单选；checked→事件由调用方 handler 消费 `event.target.checked`。 */
function selectionColumn<TData extends RowData>(L: Localize): TableColumnDef<TData> {
  return {
    id: "select",
    enableSorting: false,
    // 组件注入的列不进 Columns 菜单：藏掉它只会让「已选 N 项」无从取消，且菜单里会出现无标签项
    enableHiding: false,
    meta: { className: "w-10" },
    header: ({ table }) =>
      createElement(Checkbox, {
        checked: table.getIsAllPageRowsSelected()
          ? true
          : table.getIsSomePageRowsSelected()
            ? "indeterminate"
            : false,
        onCheckedChange: (value: boolean | "indeterminate") =>
          table.getToggleAllPageRowsSelectedHandler()({ target: { checked: value === true } }),
        "aria-label": L("Table:SelectAll"),
        // 半选只隐藏对勾，保留 indeterminate。对勾表示「全选」，拿它表示「部分」会误导；
        // aria-checked="mixed" 得留着，否则读屏会把「已选 2 行」播报成「未选中」。
        // 选了几行由紧邻上方的批量条给出。
        // tree 块的 TriStateCheckbox 半选画横线，跟这里不一样，别当不一致来「修」：
        // 那边把「部分授予」误读成「全部授予」是授权问题，这里只影响感知，不值得为它加依赖。
        className: "data-[state=indeterminate]:[&_[data-slot=checkbox-indicator]]:opacity-0",
      }),
    cell: ({ row }) =>
      createElement(Checkbox, {
        checked: row.getIsSelected(),
        onCheckedChange: (value: boolean | "indeterminate") =>
          row.getToggleSelectedHandler()({ target: { checked: value === true } }),
        onClick: (e: MouseEvent) => e.stopPropagation(),
        "aria-label": L("Table:SelectRow"),
      }),
  };
}

export interface UseDataTableOptions<TData extends RowData> {
  /** 分页/排序/选择状态机；省略则内部自建（纯客户端数据场景，不需要与外部查询参数联动）。 */
  state?: DataTableState;
  /** 列定义，引用必须稳定。`useTable` 每渲染收到新数组会重建列模型，上层所有以 columns
   *  为依赖的 memo 也跟着失效。`header` 里要用 `L()` 就包一层 `useMemo(() => [...], [L])`，
   *  `L` 的引用是稳的，等价于永久 memo。违反时 DEV 期会告警。 */
  columns: TableColumnDef<TData>[];
  data: TData[];
  pageCount?: number;
  rowCount?: number;
  selectable?: boolean;
  getRowId?: (row: TData, index: number) => string;
  /** 追加 TanStack 特性，与基础集加法合并。引用必须稳定，建议用模块级常量：`useTable` 只在
   *  挂载时构造一次表实例，特性在那时注册完，之后再变会被忽略，也不会触发重建。
   *
   *  注册不等于渲染。注册只让特性的状态和 API 可用，`DataTable` 的表现层不会自动跟上：
   *  注册 `columnResizingFeature` 后表头里没有 resize handle，注册 `rowExpandingFeature`
   *  后表体也只有 `row.getVisibleCells()`。要让它有画面就得改 `data-table.tsx`，
   *  这正是 copy-in 分发的用法。 */
  features?: Parameters<typeof tableFeatures>[0];
  /** 透传给 useTable，展开在受管选项之后，同名键调用方赢，接管即自负。
   *  `features` 走专门的 prop，类型层禁止在这里传，免得打破加法合并的不变式。 */
  tableOptions?: Omit<Partial<TableOptions<TableFeatures, TData>>, "features">;
}

export interface DataTableInstance<TData extends RowData> {
  table: TableInstance<TData>;
  state: DataTableState;
  selectedRows: TData[];
  /** 只保留这些行选中；部分失败时回填用。ids 是 `getRowId` 产出的行 ID。 */
  keepSelected: (ids: string[]) => void;
  pageCount: number;
  rowCount?: number;
  selectable: boolean;
}

/** 建 TanStack 表实例：合成勾选列、注册特性、绑定状态机、剪枝离场行的选中态。 */
export function useDataTable<TData extends RowData>(
  opts: UseDataTableOptions<TData>,
): DataTableInstance<TData> {
  const L = useLocalization();
  // hooks 必须无条件调用：外部没给 state 也要建内部状态机，只是外部给了就不用
  const internalState = useDataTableState();
  const state = opts.state ?? internalState;

  const columns = useMemo(
    () => (opts.selectable ? [selectionColumn<TData>(L), ...opts.columns] : opts.columns),
    [opts.selectable, opts.columns, L],
  );
  const tableFeatureSet = useMemo(
    () => (opts.features ? tableFeatures({ ...baseFeatureMap, ...opts.features }) : features),
    [opts.features],
  );
  // 引用比较：features 的契约本就是「必须引用稳定」，引用变本身即误用，无需比较内容。
  const mountedFeatures = useRef(opts.features);
  useEffect(() => {
    if (mountedFeatures.current !== opts.features) {
      devWarn(
        "data-table:features-changed",
        "data-table: features prop 在挂载后改变了引用，新值已被忽略。useTable 只在挂载时构造" +
          "表实例、特性注册在构造时完成，挂载后的变更不会触发重建。请把它提成模块级常量。",
      );
    }
  }, [opts.features]);
  const prevColumns = useRef(opts.columns);
  const columnsChurn = useRef(0);
  useEffect(() => {
    if (!import.meta.env.DEV) return;
    columnsChurn.current = prevColumns.current === opts.columns ? 0 : columnsChurn.current + 1;
    prevColumns.current = opts.columns;
    if (columnsChurn.current >= 3) {
      devWarn(
        "data-table:columns-churn",
        "data-table: columns 每次渲染都是新数组，表实例的列模型与上层所有以 columns 为依赖的 " +
          "memo 会全部失效。用 useMemo(() => [...], [L]) 包住——useLocalization 的 L 引用稳定，" +
          "等价于永久 memo。",
      );
    }
  });
  const table = useTable({
    features: tableFeatureSet,
    data: opts.data,
    columns,
    pageCount: opts.pageCount ?? 1,
    onPaginationChange: state.onPaginationChange,
    onSortingChange: state.onSortingChange,
    onRowSelectionChange: state.onRowSelectionChange,
    enableRowSelection: opts.selectable ?? false,
    manualPagination: true,
    manualSorting: true,
    getRowId: opts.getRowId,
    ...opts.tableOptions,
    // 一层合并而非整体覆盖：tableOptions.state 只能按键覆盖/追加受管切片，
    // 不会把 pagination/sorting/rowSelection 整体挤掉造成组件渲染与表状态失步。
    state: {
      pagination: state.pagination,
      sorting: state.sorting,
      rowSelection: state.rowSelection ?? EMPTY_ROW_SELECTION,
      ...opts.tableOptions?.state,
    },
  });

  // 行离场（删除后 refetch、外部 invalidate）时剔除对应的选中 id。选中数有两个口径：
  // 批量条显隐看 state 键数，内容看在场行数，不剪枝就会分裂出「已选 0 项」的幽灵批量条。
  // 剪枝只看当前 data，跟 keepPreviousData 天然兼容，fetching 期间旧行还在场，不会误清。
  const { data, getRowId } = opts;
  const { rowSelection, onRowSelectionChange } = state;
  useEffect(() => {
    const selected = Object.keys(rowSelection);
    if (selected.length === 0) return;
    const present = new Set(data.map((row, index) => getRowId?.(row, index) ?? String(index)));
    if (selected.every((id) => present.has(id))) return;
    onRowSelectionChange(
      Object.fromEntries(Object.entries(rowSelection).filter(([id]) => present.has(id))),
    );
  }, [data, rowSelection, onRowSelectionChange, getRowId]);

  const selectedRows = table.getSelectedRowModel().rows.map((r) => r.original);

  return {
    table,
    state,
    selectedRows,
    keepSelected: state.keepSelected,
    pageCount: opts.pageCount ?? 1,
    rowCount: opts.rowCount,
    selectable: opts.selectable ?? false,
  };
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import { flexRender, type PaginationState, type RowData } from "@tanstack/react-table";
import { ChevronDown, ChevronsUpDown, ChevronUp } from "lucide-react";
import { type ReactNode, useId } from "react";
import { DataTableFooter } from "@/components/data-table/data-table-footer";
import type { TableInstance } from "@/components/data-table/table-core";
import type { DataTableInstance } from "@/components/data-table/use-data-table";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { cn } from "@/lib/utils";

const DEFAULT_SKELETON_ROWS = 5;

function alignClass(align?: "left" | "right" | "center") {
  // 右对齐即数字列（DESIGN.md）：一并给等宽数字，否则 Inter 的比例数字宽窄不一，
  // 同列上下对不齐、跨组件（分页/页码）看着像换了字体。
  if (align === "right") return "text-right tabular-nums";
  if (align === "center") return "text-center";
  return "";
}

function justifyClass(align?: "left" | "right" | "center") {
  if (align === "right") return "justify-end";
  if (align === "center") return "justify-center";
  return "justify-start";
}

export interface DataTableProps<TData extends RowData> {
  /** 由 `useDataTable` 构造的表实例；列/数据/分页/排序/选择全部经它接入。 */
  table: DataTableInstance<TData>;
  /** 无数据可显示、正在首次取数 → 渲染骨架行。 */
  loading?: boolean;
  /** 已有数据在位、正在取新数据 → 表体降透明度。与 `loading` 互斥，react-query 下传
   *  `isFetching && !isPending`。表头不降透明度，排序仍可点，它也是用户定位刚点了什么的锚点。 */
  fetching?: boolean;
  /** 空状态。缺省是 `L("Table:Empty")` 的居中单行。传了只替换 `<td>` 内的内容，外层
   *  `<tr><td colSpan>` 仍由组件提供，不用自己算 colSpan。注意那个 `<td>` 带着
   *  `h-24 text-center text-muted-foreground`，插图 + 标题 + 按钮这类空状态会被强制居中、
   *  标题被染成 muted 色，要退出得自己在内容上加覆盖类。 */
  empty?: ReactNode;
  /** 骨架行数；缺省 5。传 `"pageSize"` 跟随当前 `pagination.pageSize`，
   *  避免 `pageSize=50` 时 5 行骨架突变成 50 行数据的跳变。 */
  skeletonRows?: number | "pageSize";
  /** 行级属性，只开 `className`。事件走 `onRowClick`，万能透传会让调用方覆盖掉
   *  `key`/`data-state` 这些组件自管的东西。收 `row.original` 而不是 `Row`，要判断的是业务
   *  状态而非表格行状态。不需要引用稳定，它不进任何 memo 依赖，只在渲染时调用。
   *
   *  要覆盖悬停态或选中态得自带对应变体，例如
   *  `{ className: "bg-red-50 hover:bg-red-50 data-[state=selected]:bg-red-50" }`。
   *  只给 `bg-red-50` 的话，组件自带的 `hover:bg-muted/50` 和
   *  `data-[state=selected]:bg-row-selected` 修饰符不同，tailwind-merge 不去重，
   *  悬停和选中时又特异性更高，会把你的颜色盖回去。 */
  rowProps?: (row: TData) => { className?: string };
  onRowClick?: (row: TData) => void;
  /** 每页条数选项，缺省 `[10, 20, 50]`。当前 `pagination.pageSize` 总会被并入去重升序，
   *  所以传了 `useDataTable({ defaultPageSize })` 忘了同步这里，触发器也不会空白。
   *  传了 `footer` 则本项不生效。 */
  pageSizes?: number[];
  /** 接管整个页脚区：总条数文字、每页行数下拉、分页器三者全部。缺省渲染内建页脚。
   *  做「加载更多」或无限滚动的调用方本就不要页码和每页行数，拆开接管只会让他们分别关
   *  三个开关；要保留哪部分自己从 ctx 拼，分页动作走 `ctx.table.nextPage()` 这些。
   *  传了它之后 `pageSizes` 不生效，内建的每页行数下拉不再渲染。 */
  footer?: (ctx: {
    table: TableInstance<TData>;
    pagination: PaginationState;
    pageCount: number;
    rowCount?: number;
  }) => ReactNode;
  /** 工具栏等散件，渲染在卡片内部、表格上方，顺序即摆放顺序。 */
  children?: ReactNode;
}

/** 服务端分页的通用表格。实例由 `useDataTable` 构造后传入，本组件只管表现层：
 *  骨架、空态、表头表体和内建页脚。行操作列由调用方当普通 column 传进来。 */
export function DataTable<TData extends RowData>(props: DataTableProps<TData>) {
  const L = useLocalization();
  const tableId = useId();
  const { table: dt } = props;
  const table = dt.table;
  const skeletonCount =
    props.skeletonRows === "pageSize"
      ? dt.state.pagination.pageSize
      : (props.skeletonRows ?? DEFAULT_SKELETON_ROWS);

  const footerContent = props.footer ? (
    props.footer({
      table,
      pagination: dt.state.pagination,
      pageCount: dt.pageCount,
      rowCount: dt.rowCount,
    })
  ) : (
    <DataTableFooter
      table={table}
      pagination={dt.state.pagination}
      pageCount={dt.pageCount}
      rowCount={dt.rowCount}
      pageSizes={props.pageSizes}
    />
  );

  return (
    <div className="overflow-hidden rounded-md border bg-card">
      {props.children}
      <Table
        className={cn(dt.state.density === "compact" && "[&_td]:py-1")}
        aria-busy={props.loading || props.fetching ? true : undefined}
      >
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                const showSortIndex =
                  table.state.sorting.length > 1 && Boolean(header.column.getIsSorted());
                const sortPriorityId = `${tableId}-sortpri-${header.id}`;
                return (
                  <TableHead
                    key={header.id}
                    aria-sort={
                      header.column.getIsSorted() === "asc"
                        ? "ascending"
                        : header.column.getIsSorted() === "desc"
                          ? "descending"
                          : header.column.getCanSort()
                            ? "none"
                            : undefined
                    }
                    className={cn(
                      // label-caps：正字距的大写小字把表头标记为"分类"而非内容，
                      // 是这套系统里唯一用正字距的地方（DESIGN.md Typography）。
                      "bg-muted/50 text-xs font-medium uppercase tracking-wide text-muted-foreground",
                      alignClass(header.column.columnDef.meta?.align),
                      header.column.columnDef.meta?.className,
                    )}
                  >
                    {header.isPlaceholder ? null : header.column.getCanSort() ? (
                      <button
                        type="button"
                        onClick={header.column.getToggleSortingHandler()}
                        aria-describedby={showSortIndex ? sortPriorityId : undefined}
                        className={cn(
                          "inline-flex w-full items-center gap-1.5 select-none hover:text-foreground",
                          "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                          justifyClass(header.column.columnDef.meta?.align),
                        )}
                      >
                        {flexRender(header.column.columnDef.header, header.getContext())}
                        {header.column.getIsSorted() === "asc" ? (
                          <ChevronUp className="size-3 text-primary" />
                        ) : header.column.getIsSorted() === "desc" ? (
                          <ChevronDown className="size-3 text-primary" />
                        ) : (
                          <ChevronsUpDown className="size-3 opacity-50" />
                        )}
                        {showSortIndex && (
                          // 优先级本就不可用 ARIA 表达（aria-sort 只有方向），裸数字留在可访问名里
                          // 会污染读屏播报与语音控制的匹配目标（按钮会变成「Name1」而非「Name」）。
                          <span
                            aria-hidden="true"
                            className="text-2xs font-normal tabular-nums text-muted-foreground"
                          >
                            {header.column.getSortIndex() + 1}
                          </span>
                        )}
                      </button>
                    ) : (
                      flexRender(header.column.columnDef.header, header.getContext())
                    )}
                    {showSortIndex && (
                      // 描述得放 button 外面，进 button 会并入可访问名、污染语音控制的匹配目标，
                      // 而 aria-describedby 只影响描述不影响名称。但 th 自己也是 "name from
                      // content" 的角色，不加 aria-hidden 这段文字照样会并进表头的可访问名。
                      // aria-hidden 把它逐出常规内容遍历，aria-describedby 的直接引用不受影响，
                      // 读屏仍读得到。
                      <span id={sortPriorityId} aria-hidden="true" className="sr-only">
                        {L("Table:SortPriority", header.column.getSortIndex() + 1)}
                      </span>
                    )}
                  </TableHead>
                );
              })}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody
          className={cn(
            // delay-100 吃掉快请求的闪烁，100ms 内返回的几乎看不出变化，且不用 JS 定时器。
            // 没加 pointer-events-none：它只挡鼠标不挡键盘，两类用户会拿到不同能力；
            // keepPreviousData 期间在位的又正是上一次的有效数据，点它并不危险（行操作打的是
            // id，行真没了服务端会 404）。「正在刷新」靠降透明度 + aria-busy 表达，不禁用交互。
            props.fetching && "opacity-60 transition-opacity duration-150 delay-100",
          )}
        >
          {props.loading ? (
            Array.from({ length: skeletonCount }, (_, i) => (
              // biome-ignore lint/suspicious/noArrayIndexKey: 骨架占位行数固定且从不重排
              <TableRow key={`skeleton-${i}`}>
                <TableCell colSpan={table.getVisibleLeafColumns().length}>
                  <Skeleton className="h-5 w-full" />
                </TableCell>
              </TableRow>
            ))
          ) : table.getRowModel().rows.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={table.getVisibleLeafColumns().length}
                className="h-24 text-center text-muted-foreground"
              >
                {props.empty ?? L("Table:Empty")}
              </TableCell>
            </TableRow>
          ) : (
            table.getRowModel().rows.map((row) => (
              <TableRow
                key={row.id}
                data-state={row.getIsSelected() ? "selected" : undefined}
                className={cn(
                  "group hover:bg-muted/50 data-[state=selected]:bg-row-selected",
                  props.onRowClick &&
                    "cursor-pointer focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring",
                  props.rowProps?.(row.original)?.className,
                )}
                tabIndex={props.onRowClick ? 0 : undefined}
                onClick={() => props.onRowClick?.(row.original)}
                onKeyDown={
                  props.onRowClick &&
                  ((e) => {
                    if (e.key === "Enter" || e.key === " ") {
                      // 两个都要 preventDefault。Space 默认滚动页面；Enter 会在本次按键继续合成
                      // 一次 click，落到激活后新获得焦点的元素上（详情抽屉里的「编辑」按钮），
                      // 键盘激活就越过详情态直接进了编辑态。
                      // 行操作菜单已在自己的 onKeyDown 里 stopPropagation，不会误触发行激活。
                      e.preventDefault();
                      props.onRowClick?.(row.original);
                    }
                  })
                }
              >
                {row.getVisibleCells().map((cell) => (
                  <TableCell
                    key={cell.id}
                    className={cn(
                      alignClass(cell.column.columnDef.meta?.align),
                      cell.column.columnDef.meta?.className,
                    )}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
      {/* footer 返回 falsy（无限滚动这类不要页脚的接管）时连外壳一起不渲染，
          否则卡片底部会留一条 1px 上边框加一段空白。 */}
      {footerContent ? <div className="border-t px-3 py-2">{footerContent}</div> : null}
    </div>
  );
}

import { useLocalization } from "@jcoder-stack/abp-react/react";
import type { PaginationState, RowData } from "@tanstack/react-table";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { type ReactNode, useMemo } from "react";
import type { TableInstance } from "@/components/data-table/table-core";
import {
  Pagination,
  PaginationContent,
  PaginationEllipsis,
  PaginationItem,
  PaginationLink,
} from "@/components/ui/pagination";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

const DEFAULT_PAGE_SIZES = [10, 20, 50];
const PAGE_WINDOW_THRESHOLD = 7;

/** 0-based 页码窗口：总页 ≤7 全显；否则首页/末页恒在，加当前页及左右各一页，其余折叠为省略号。 */
export function getPageItems(pageIndex: number, pageCount: number): (number | "ellipsis")[] {
  const totalPages = Math.max(pageCount, 1);
  if (totalPages <= PAGE_WINDOW_THRESHOLD) {
    return Array.from({ length: totalPages }, (_, i) => i);
  }

  const current = Math.min(Math.max(pageIndex, 0), totalPages - 1);
  const keep = new Set<number>([0, totalPages - 1, current]);
  if (current - 1 >= 0) keep.add(current - 1);
  if (current + 1 <= totalPages - 1) keep.add(current + 1);
  const sorted = [...keep].sort((a, b) => a - b);

  const items: (number | "ellipsis")[] = [];
  let previous: number | undefined;
  for (const page of sorted) {
    if (previous !== undefined && page - previous > 1) items.push("ellipsis");
    items.push(page);
    previous = page;
  }
  return items;
}

/** 内建页脚：总条数 + 每页行数下拉 + 分页器。与表体正交，单独成文件降低 fork 进入成本。 */
export function DataTableFooter<TData extends RowData>(props: {
  table: TableInstance<TData>;
  pagination: PaginationState;
  pageCount: number;
  rowCount?: number;
  pageSizes?: number[];
}): ReactNode {
  const L = useLocalization();
  const { table } = props;
  const canPrev = table.getCanPreviousPage();
  const canNext = table.getCanNextPage();
  const pageItems = getPageItems(props.pagination.pageIndex, props.pageCount);

  const sizeOptions = useMemo(() => {
    const merged = new Set([...(props.pageSizes ?? DEFAULT_PAGE_SIZES), props.pagination.pageSize]);
    return [...merged].sort((a, b) => a - b);
  }, [props.pageSizes, props.pagination.pageSize]);

  const prevItem = (
    <PaginationItem>
      <PaginationLink
        size="icon"
        className={cn("size-8", !canPrev && "pointer-events-none opacity-50")}
        aria-label={L("Table:Previous")}
        aria-disabled={!canPrev}
        href={canPrev ? "#" : undefined}
        onClick={(e) => {
          e.preventDefault();
          if (canPrev) table.previousPage();
        }}
      >
        <ChevronLeft />
      </PaginationLink>
    </PaginationItem>
  );

  const nextItem = (
    <PaginationItem>
      <PaginationLink
        size="icon"
        className={cn("size-8", !canNext && "pointer-events-none opacity-50")}
        aria-label={L("Table:Next")}
        aria-disabled={!canNext}
        href={canNext ? "#" : undefined}
        onClick={(e) => {
          e.preventDefault();
          if (canNext) table.nextPage();
        }}
      >
        <ChevronRight />
      </PaginationLink>
    </PaginationItem>
  );

  return (
    <div className="flex items-center justify-between gap-2">
      <div className="flex items-center gap-2 text-sm tabular-nums text-muted-foreground">
        {props.rowCount !== undefined && props.rowCount > 0 && (
          <span>{L("Table:Total", props.rowCount)}</span>
        )}
        <span>{L("Table:RowsPerPage")}</span>
        <Select
          value={String(props.pagination.pageSize)}
          onValueChange={(v: string) => table.setPagination({ pageIndex: 0, pageSize: Number(v) })}
        >
          <SelectTrigger size="sm" className="tabular-nums">
            <SelectValue />
          </SelectTrigger>
          <SelectContent className="tabular-nums">
            {sizeOptions.map((size) => (
              <SelectItem key={size} value={String(size)}>
                {size}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="flex items-center gap-2">
        <span className="text-sm tabular-nums text-muted-foreground md:hidden">
          {L("Table:PageOf", props.pagination.pageIndex + 1, Math.max(props.pageCount, 1))}
        </span>
        <Pagination className="mx-0 w-auto md:hidden">
          <PaginationContent>
            {prevItem}
            {nextItem}
          </PaginationContent>
        </Pagination>
        <Pagination className="mx-0 hidden w-auto md:flex">
          <PaginationContent>
            {prevItem}
            {pageItems.map((item, i) =>
              item === "ellipsis" ? (
                // biome-ignore lint/suspicious/noArrayIndexKey: 省略号在窗口内位置固定，不参与重排
                <PaginationItem key={`ellipsis-${i}`}>
                  <PaginationEllipsis />
                </PaginationItem>
              ) : (
                <PaginationItem key={item}>
                  <PaginationLink
                    size="icon"
                    className={cn(
                      "size-8 tabular-nums",
                      item === props.pagination.pageIndex &&
                        "border-primary bg-primary text-primary-foreground hover:bg-primary-hover hover:text-primary-foreground dark:border-primary dark:bg-primary dark:hover:bg-primary-hover",
                    )}
                    isActive={item === props.pagination.pageIndex}
                    href="#"
                    onClick={(e) => {
                      e.preventDefault();
                      table.setPageIndex(item);
                    }}
                  >
                    {item + 1}
                  </PaginationLink>
                </PaginationItem>
              ),
            )}
            {nextItem}
          </PaginationContent>
        </Pagination>
      </div>
    </div>
  );
}

