const UTILITY_ICON_CLASS = "size-8 text-muted-foreground";

export interface DataTableToolbarProps<TData extends RowData> {
  table: DataTableInstance<TData>;
  /** 是否渲染内建搜索框；缺省 true。传了 `left` 时搜索框让位。 */
  search?: boolean;
