  utilityLeading?: ReactNode;
  /** trailing 区：列显隐菜单等散件，并入右侧功能图标组。 */
  children?: ReactNode;
}

/** 表格卡片顶部条：左区三态（自定义内容/搜索框 ⇄ 批量操作），右区恒定
 * （actions │ utilityLeading · 刷新 · 导出 · 密度 · trailing）。Enter 立即提交搜索。 */
export function DataTableToolbar<TData extends RowData>(props: DataTableToolbarProps<TData>) {
  const L = useLocalization();
  const { state } = props.table;
  const showSearch = props.search ?? true;
  const bulkActive = props.bulk !== undefined && props.table.selectedRows.length > 0;

  const left = bulkActive
    ? props.bulk
    : (props.left ??
      (showSearch ? (
        <Input
          className="h-8 w-56"
          value={state.searchInput}
          placeholder={props.searchPlaceholder ?? L("Table:Search")}
          onChange={(e) => state.setSearch(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && state.flushSearch()}
        />
      ) : null));

  return (
    <div className="flex flex-wrap items-center gap-2 border-b px-3 py-2">
      {left}
      <div className="ml-auto flex items-center gap-2">
        {props.actions}
        {props.actions ? <Separator orientation="vertical" className="mx-1 !h-5" /> : null}
        <div className="flex items-center gap-1">
          {props.utilityLeading}
          {props.onRefresh && (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className={UTILITY_ICON_CLASS}
                  aria-label={L("Table:Refresh")}
                  onClick={props.onRefresh}
                >
                  <RefreshCw className={cn(props.refreshing && "animate-spin")} />
                </Button>
              </TooltipTrigger>
              {/* 不只重复「刷新」二字:这颗钮容易被误解为重置,提示里写清语义——重发当前查询,筛选保留 */}
              <TooltipContent>{L("Table:RefreshTip")}</TooltipContent>
            </Tooltip>
          )}
          {props.onExport && (
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  type="button"
                  variant="ghost"
                  size="icon"
                  className={UTILITY_ICON_CLASS}
                  aria-label={L("Table:Export")}
                  onClick={props.onExport}
                >
                  <Download />
                </Button>
              </TooltipTrigger>
              <TooltipContent>{L("Table:Export")}</TooltipContent>
            </Tooltip>
          )}
          <DropdownMenu>
            <Tooltip>
              <TooltipTrigger asChild>
                <DropdownMenuTrigger asChild>
                  <Button
                    type="button"
                    variant="ghost"
                    size="icon"
                    className={UTILITY_ICON_CLASS}
                    aria-label={L("Table:Density")}
                  >
                    <Rows3 />
                  </Button>
                </DropdownMenuTrigger>
              </TooltipTrigger>
              <TooltipContent>{L("Table:Density")}</TooltipContent>
            </Tooltip>
            <DropdownMenuContent align="end">
              <DropdownMenuRadioGroup
                value={state.density}
                onValueChange={(value) => {
                  // 收窄而非断言：菜单项之外的值（将来加档位忘了同步这里）宁可无声忽略，
                  // 也不要把非法字符串塞进状态机。
                  if (value === "comfortable" || value === "compact") state.setDensity(value);
                }}
              >
                <DropdownMenuRadioItem value="comfortable">
                  {L("Table:DensityComfortable")}
                </DropdownMenuRadioItem>
                <DropdownMenuRadioItem value="compact">
                  {L("Table:DensityCompact")}
                </DropdownMenuRadioItem>
              </DropdownMenuRadioGroup>
            </DropdownMenuContent>
          </DropdownMenu>
          {props.children}
        </div>
      </div>
    </div>
  );
}

import type { HeaderContext, RowData } from "@tanstack/react-table";
import { flexRender } from "@tanstack/react-table";
import type { ReactNode } from "react";
import type { CellTableInstance, TableFeatures } from "@/components/data-table/table-core";

/** 列标签解析阶梯：meta.label → 表头 flexRender 结果（与表头逐字一致）→ 隐藏列兜底直调
 * header 渲染器 → column.id。
 *
 * 契约：列隐藏后 `getHeaderGroups()`（进而 `getFlatHeaders()`）不会给出该列的表头对象，v9
 * 引擎在 `getVisibleLeafColumns()` 就把它筛掉了。兜底分支不含真实 `header`，只拼一个
 * `{ table, column }` 上下文调用 `columnDef.header`；若你的 header 渲染器读取上下文里的
 * `header` 字段，请改设 `meta.label` 显式指定菜单文案。 */
export function resolveColumnLabel<TData extends RowData>(
  table: CellTableInstance<TData>,
  columnId: string,
): ReactNode {
  const column = table.getAllLeafColumns().find((c) => c.id === columnId);
  const metaLabel = column?.columnDef.meta?.label;
  if (metaLabel !== undefined) return metaLabel;
  const header = table.getFlatHeaders().find((h) => h.column.id === columnId);
  if (header && !header.isPlaceholder) {
    return flexRender(header.column.columnDef.header, header.getContext());
  }
  if (!column) return columnId;
  const rawHeader = column.columnDef.header;
  if (typeof rawHeader === "string") return rawHeader;
  if (typeof rawHeader === "function") {
    // 隐藏列没有 Header 实例可用；用真实 table/column 拼一个残缺上下文喂给渲染器，仅本文件内断言。
    const context = { table, column } as HeaderContext<TableFeatures, TData, unknown>;
    return rawHeader(context);
  }
  return columnId;
}

